// ── Input Validation ──
// Checks that the incoming request has valid code and a supported language.

const items = $input.all();
const results = [];

for (const item of items) {
  const code = item.json.body?.code || item.json.code || '';
  const language = (item.json.body?.language || item.json.language || '').toLowerCase().trim();

  // Supported languages list
  const supportedLanguages = [
    'python', 'javascript', 'typescript', 'java', 'c', 'cpp', 'c++',
    'csharp', 'c#', 'go', 'rust', 'ruby', 'php', 'swift', 'kotlin',
    'scala', 'r', 'sql', 'bash', 'shell', 'powershell', 'html', 'css',
    'yaml', 'json', 'xml', 'dockerfile', 'terraform', 'hcl'
  ];

  // Programming keywords that indicate real code (not random text)
  const codeKeywords = [
    'function', 'def ', 'class ', 'import ', 'from ', 'return',
    'const ', 'let ', 'var ', 'if ', 'else', 'for ', 'while ',
    'print', 'console', 'public ', 'private ', 'void ', 'int ',
    'string', 'static', 'async', 'await', 'try', 'catch',
    'switch', 'case', 'break', 'continue', 'new ', 'this',
    'self', 'require', 'module', 'export', 'include', 'using',
    'package', 'struct', 'enum', 'interface', 'impl ', 'fn ',
    'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'CREATE', 'DROP',
    'func ', 'fmt.', 'println', 'BEGIN', 'END', '#include',
    '=>', '->', '===', '!==', '==', '!=', '&&', '||',
    '{', '}', '()', ';', '//', '/*', '*/', '#!/'
  ];

  const errors = [];

  // Check: code must not be empty
  if (!code || code.trim().length === 0) {
    errors.push('Code field is empty or missing.');
  }

  // Check: code should look like actual code
  if (code && code.trim().length > 0) {
    const looksLikeCode = codeKeywords.some(kw =>
      code.toLowerCase().includes(kw.toLowerCase())
    );
    if (!looksLikeCode && code.trim().length < 10) {
      errors.push('Input does not appear to be valid code.');
    }
  }

  // Check: language must be provided and supported
  if (!language) {
    errors.push('Language field is missing.');
  } else if (!supportedLanguages.includes(language)) {
    errors.push(`Unsupported language: '${language}'. Supported: ${supportedLanguages.join(', ')}`);
  }

  const isValid = errors.length === 0;

  results.push({
    json: {
      isValid: isValid,
      code: code,
      language: language,
      errors: errors,
      validationMessage: isValid
        ? 'Input is valid.'
        : `Validation failed: ${errors.join(' ')}`
    }
  });
}

return results;

