// ── Parse LLM Response ──
// Extracts the JSON review from the Groq chat completion response
// and determines the overall severity level.

const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Extract the assistant's message content
    const rawContent = item.json.choices?.[0]?.message?.content || '';

    // Try to parse JSON — handle cases where LLM wraps it in markdown code blocks
    let cleaned = rawContent.trim();
    if (cleaned.startsWith('```json')) {
      cleaned = cleaned.slice(7);
    } else if (cleaned.startsWith('```')) {
      cleaned = cleaned.slice(3);
    }
    if (cleaned.endsWith('```')) {
      cleaned = cleaned.slice(0, -3);
    }
    cleaned = cleaned.trim();

    const review = JSON.parse(cleaned);

    // Determine the highest severity found
    const issues = review.issues || [];
    let severity = 'clean';

    if (issues.some(i => i.severity === 'critical')) {
      severity = 'critical';
    } else if (issues.some(i => i.severity === 'warning')) {
      severity = 'warning';
    } else if (issues.length > 0) {
      severity = 'info';
    }

    // Carry forward the original code and language for the deep analysis node
    const prevData = $('Input Validation').first().json;

    results.push({
      json: {
        review: review,
        severity: severity,
        issueCount: issues.length,
        code: prevData.code,
        language: prevData.language,
        model: item.json.model || 'llama-3.3-70b-versatile',
        tokensUsed: item.json.usage?.total_tokens || 0,
        parseSuccess: true
      }
    });
  } catch (error) {
    results.push({
      json: {
        review: {
          summary: 'Failed to parse LLM response.',
          issues: [],
          metrics: {
            readability: 0,
            maintainability: 0,
            security: 0,
            performance: 0,
            overall: 0
          }
        },
        severity: 'info',
        issueCount: 0,
        parseSuccess: false,
        parseError: error.message
      }
    });
  }
}

return results;

