// ── Format Final Report ──
// Compiles the review (and optional deep analysis) into a structured JSON report.

const items = $input.all();
const results = [];

for (const item of items) {
  // Try to get the parsed review data — it might come from different paths
  let reviewData;
  try {
    reviewData = $('Parse LLM Response').first().json;
  } catch (e) {
    reviewData = item.json;
  }

  const review = reviewData.review || item.json.review || {};
  const severity = reviewData.severity || item.json.severity || 'info';
  const code = reviewData.code || item.json.code || '';
  const language = reviewData.language || item.json.language || '';

  // Check if this item came through the deep analysis path
  let deepAnalysis = null;
  try {
    const deepResponse = $('Groq - Deep Analysis').first().json;
    if (deepResponse && deepResponse.choices) {
      let deepContent = deepResponse.choices[0]?.message?.content || '';
      deepContent = deepContent.trim();
      if (deepContent.startsWith('```json')) deepContent = deepContent.slice(7);
      if (deepContent.startsWith('```')) deepContent = deepContent.slice(3);
      if (deepContent.endsWith('```')) deepContent = deepContent.slice(0, -3);
      deepAnalysis = JSON.parse(deepContent.trim()).deepAnalysis;
    }
  } catch (e) {
    // No deep analysis available — that's fine for non-critical paths
    deepAnalysis = null;
  }

  // Build the final report
  const report = {
    status: 'success',
    timestamp: new Date().toISOString(),
    input: {
      language: language,
      codeLength: code.length,
      codePreview: code.substring(0, 100) + (code.length > 100 ? '...' : '')
    },
    review: {
      summary: review.summary || 'No summary available.',
      severity: severity,
      issueCount: (review.issues || []).length,
      issues: (review.issues || []).map(issue => ({
        severity: issue.severity || 'info',
        category: issue.category || 'general',
        line: issue.line || 'N/A',
        description: issue.description || '',
        suggestion: issue.suggestion || ''
      })),
      metrics: review.metrics || {
        readability: 0,
        maintainability: 0,
        security: 0,
        performance: 0,
        overall: 0
      }
    },
    deepAnalysis: deepAnalysis,
    metadata: {
      model: reviewData.model || 'llama-3.3-70b-versatile',
      tokensUsed: reviewData.tokensUsed || 0,
      engine: 'n8n-workflow',
      version: '1.0.0'
    }
  };

  results.push({ json: report });
}

return results;
